import {GOAT} from './goat-config.js';
/** @param {Pick<import('./goat-state.js').Paddock,'biomassG'>} paddock @param {import('./engine.js').Weather} weather @param {boolean} resting */
export function goatRegrowth(paddock,weather,resting){const factors={sunny:1,cloudy:1.1,rainy:1.5,hot:.55},rate=GOAT.regrowthDayG/24*factors[weather]*(resting?1:.25);return Math.max(0,Math.min(GOAT.paddockMaxG-paddock.biomassG,rate));}
/** One existing farm hour: browse first, then stored hay meets the remaining demand. No extra RNG or timer. @param {import('./goat-state.js').GoatState} g @param {import('./engine.js').Weather} weather */
export function browseGoatHour(g,weather){const demand=g.herd.length*GOAT.foodDayG/24,p=g.paddocks[g.activePaddock],browse=Math.min(demand,p.biomassG);p.biomassG=Math.max(0,p.biomassG-browse);p.usedG+=browse;g.stats.browseUsedG+=browse;if(p.restHours>=24)g.stats.restedBrowseG+=browse;for(const paddock of g.paddocks){const resting=paddock.id!==g.activePaddock,amount=goatRegrowth(paddock,weather,resting);paddock.biomassG+=amount;paddock.regrownG+=amount;paddock.restHours=resting?paddock.restHours+1:0;}return {demand,browse,remaining:Math.max(0,demand-browse)};}
